+.miniTable th{font-size:10px}
+
+.chartToolbar{
+  display:flex;
+  flex-wrap:wrap;
+  align-items:center;
+  gap:8px;
+}
+.toolBtn{
+  cursor:pointer;
+  border:1px solid var(--stroke);
+  background:rgba(255,255,255,.03);
+  color:var(--muted);
+  padding:8px 10px;
+  border-radius:12px;
+  font-size:12px;
+  display:inline-flex;
+  align-items:center;
+  gap:8px;
+}
+.toolBtn.active{color:var(--text); border-color:rgba(41,98,255,.45); background:rgba(41,98,255,.12)}
+.toolBtn:focus{outline:none; box-shadow:var(--focus)}
+
+.chartArea{height:420px; display:grid; grid-template-rows:auto 1fr auto; gap:10px}
+.chartHeader{display:flex; align-items:center; justify-content:space-between; gap:10px}
+.symbolRow{display:flex; align-items:baseline; gap:10px; flex-wrap:wrap}
+.symbolRow strong{font-size:15px}
+.symbolRow .badge{font-size:11px}
+.chartCanvas{
+  position:relative;
+  border-radius:var(--radius);
+  border:1px solid var(--stroke);
+  overflow:hidden;
+  background:linear-gradient(180deg, rgba(8,10,20,.55), rgba(4,5,10,.65));
+}
+.chartCanvas canvas{width:100%; height:100%; display:block}
+.chartOverlay{
+  position:absolute; inset:0;
+  pointer-events:none;
+  background:
+    linear-gradient(90deg, rgba(255,255,255,.05) 1px, transparent 1px) 0 0 / 64px 100%,
+    linear-gradient(180deg, rgba(255,255,255,.05) 1px, transparent 1px) 0 0 / 100% 48px;
+  opacity:.35;
+}
+.chartFooter{display:flex; align-items:center; justify-content:space-between; gap:10px; flex-wrap:wrap}
+.tfGroup{display:flex; gap:8px; flex-wrap:wrap}
+
+.detailTabs{display:flex; gap:8px; flex-wrap:wrap; margin-bottom:10px}
+.statGrid{display:grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap:10px}
+.stat{
+  padding:10px;
+  border:1px solid var(--stroke);
+  border-radius:12px;
+  background:rgba(255,255,255,.02);
+}
+.stat label{display:block; font-size:11px; color:var(--muted); text-transform:uppercase; letter-spacing:.12em; margin-bottom:6px}
+.stat div{font-family:var(--mono); font-size:13px}
+
*** End Patch
PATCH

